/* ------------------------------------------------------------------ */
function ScientificReferences({
  citations,
}: {
  citations: ReferenceItem[];
}) {
  return (
    <section className="references-section">
      <h2 className="text-2xl font-bold text-gray-900">Scientific References</h2>
      <p className="ref-intro">All references fetched directly from PubMed and CrossRef before article generation.</p>
      <div className="ref-list">
        {citations.map((c, i) => (
          <div key={c.id} className={`ref-item${c.status !== "verified" ? " unverified" : ""}`}>
            <span className="ref-num">[{i + 1}]</span>
            <p className="ref-content">
              <span className="ref-authors">{c.authors} ({c.year}).</span>{" "}
              {c.url ? (
                <a href={c.url} target="_blank" rel="noopener noreferrer" className="ref-title-link">
                  {c.title}
                </a>
              ) : (
                <span className="ref-title-plain">{c.title}</span>
              )}
              . <em className="ref-journal">{c.journal}</em>.{" "}
              {c.studyType && <span className="ref-badge ref-studytype">{c.studyType}</span>}
              {c.doi && <span className="ref-badge ref-doi">DOI: {c.doi}</span>}
              {c.pmid && (
                <a
                  href={`https://pubmed.ncbi.nlm.nih.gov/${c.pmid}/`}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="ref-badge ref-pmid"
                >
                  PMID {c.pmid}
                </a>
              )}
            </p>
          </div>
        ))}
      </div>
      <div className="ref-review">
        ❤️ <strong>Reviewed by ThriveHealth360 Editorial Team. References verified via CrossRef &amp; PubMed.</strong>
      </div>
    </section>
  );
}

